import{c as a,Q as e,j as s,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Dynamic Workflows 完整指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/32-dynamic-workflows.md","filePath":"research/best-practices/32-dynamic-workflows.md","lastUpdated":1780842316000}'),r={name:"research/best-practices/32-dynamic-workflows.md"};function n(l,t,i,d,c,p){return e(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="dynamic-workflows-完整指南" tabindex="-1">Dynamic Workflows 完整指南 <a class="header-anchor" href="#dynamic-workflows-完整指南" aria-label="Permalink to &quot;Dynamic Workflows 完整指南&quot;">​</a></h1><blockquote><p>來源：</p><ul><li><a href="https://claude.com/blog/introducing-dynamic-workflows-in-claude-code" target="_blank" rel="noreferrer">Introducing dynamic workflows in Claude Code</a>（2026-05-28）</li><li><a href="https://claude.com/blog/a-harness-for-every-task-dynamic-workflows-in-claude-code" target="_blank" rel="noreferrer">A harness for every task: dynamic workflows in Claude Code</a>（2026-06-02）<br> 作者：Thariq Shihipar、Sid Bidasaria（Anthropic）<br> 整理日期：2026-06-05<br> 版本：W22（v2.1.150–v2.1.157）</li></ul></blockquote><hr><h2 id="什麼是-dynamic-workflows" tabindex="-1">什麼是 Dynamic Workflows <a class="header-anchor" href="#什麼是-dynamic-workflows" aria-label="Permalink to &quot;什麼是 Dynamic Workflows&quot;">​</a></h2><p>Claude 根據任務動態撰寫並執行 JavaScript 協調腳本，可在同一 session 中協調數十到數百個並行 subagent。</p><blockquote><p>&quot;Claude can now write its own harness on the fly, custom-built for the task at hand.&quot;</p></blockquote><p><strong>解決的三個失敗模式：</strong></p><table tabindex="0"><thead><tr><th>失敗模式</th><th>說明</th></tr></thead><tbody><tr><td>Agentic laziness</td><td>複雜多步驟任務中提前停止</td></tr><tr><td>Self-preferential bias</td><td>需要驗證時偏向自己的結果</td></tr><tr><td>Goal drift</td><td>連續摘要導致目標漂移</td></tr></tbody></table><hr><h2 id="啟動方式" tabindex="-1">啟動方式 <a class="header-anchor" href="#啟動方式" aria-label="Permalink to &quot;啟動方式&quot;">​</a></h2><p><strong>方法一</strong>：直接請求</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; create a workflow that migrates every internal fetch() call to the new HttpClient wrapper</span></span></code></pre></div><p><strong>方法二</strong>：啟用 ultracode 設定（讓 Claude 自行決定何時使用 workflow）</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; /effort ultracode</span></span></code></pre></div><p>管理執行中的 workflows：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; /workflows</span></span></code></pre></div><hr><h2 id="六大-workflow-模式" tabindex="-1">六大 Workflow 模式 <a class="header-anchor" href="#六大-workflow-模式" aria-label="Permalink to &quot;六大 Workflow 模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>說明</th><th>適用場景</th></tr></thead><tbody><tr><td><strong>Classify-and-act</strong></td><td>依任務類型路由到不同 agent</td><td>Issue triage、文件分類</td></tr><tr><td><strong>Fan-out-and-synthesize</strong></td><td>並行分散 → 合併結果</td><td>大型 codebase 搜尋、研究報告</td></tr><tr><td><strong>Adversarial verification</strong></td><td>獨立 agent 驗證輸出</td><td>事實核查、安全審查</td></tr><tr><td><strong>Generate-and-filter</strong></td><td>生成候選 → 依品質篩選</td><td>程式碼生成、創意工作</td></tr><tr><td><strong>Tournament</strong></td><td>競爭 agent 解題 → 兩兩評判</td><td>排序、最佳解尋找</td></tr><tr><td><strong>Loop until done</strong></td><td>持續生成直到停止條件</td><td>遷移、批次處理</td></tr></tbody></table><hr><h2 id="技術能力" tabindex="-1">技術能力 <a class="header-anchor" href="#技術能力" aria-label="Permalink to &quot;技術能力&quot;">​</a></h2><ul><li><strong>模型選擇</strong>：workflow 決定每個 subagent 使用哪個 Claude 模型</li><li><strong>隔離</strong>：subagent 可在獨立 worktree 執行，context 完全隔離</li><li><strong>續接</strong>：中斷的 workflow 可從最後 checkpoint 恢復</li><li><strong>整合</strong>：與 <code>/goal</code>、<code>/loop</code> 指令相容</li></ul><hr><h2 id="實際應用案例" tabindex="-1">實際應用案例 <a class="header-anchor" href="#實際應用案例" aria-label="Permalink to &quot;實際應用案例&quot;">​</a></h2><h3 id="大型遷移" tabindex="-1">大型遷移 <a class="header-anchor" href="#大型遷移" aria-label="Permalink to &quot;大型遷移&quot;">​</a></h3><p>Bun 用 dynamic workflows 將 ~750,000 行從 Zig porting 到 Rust，11 天完成，通過 99.8% 既有測試：</p><ul><li>一個 workflow 處理 lifetime mapping</li><li>並行 agents 完成各檔案 porting，每檔有雙重 reviewer</li></ul><h3 id="深度研究" tabindex="-1">深度研究 <a class="header-anchor" href="#深度研究" aria-label="Permalink to &quot;深度研究&quot;">​</a></h3><p><code>/deep-research</code> skill 內部使用 fan-out 並行 web 搜尋 + adversarial 驗證。</p><h3 id="大型-codebase-審查" tabindex="-1">大型 Codebase 審查 <a class="header-anchor" href="#大型-codebase-審查" aria-label="Permalink to &quot;大型 Codebase 審查&quot;">​</a></h3><p>全 codebase 安全 audit：並行搜尋 → 獨立驗證 → 整合報告。</p><hr><h2 id="何時使用-vs-何時不用" tabindex="-1">何時使用 vs 何時不用 <a class="header-anchor" href="#何時使用-vs-何時不用" aria-label="Permalink to &quot;何時使用 vs 何時不用&quot;">​</a></h2><p><strong>使用情境：</strong></p><ul><li>任務太大，單一 context window 無法協調</li><li>需要並行化或獨立驗證</li><li>高價值、複雜、反覆精煉</li></ul><p><strong>不使用情境：</strong></p><ul><li>標準編碼任務（不需多 agent 協調）</li><li>Token 成本敏感任務（workflows 消耗明顯更多 token）</li></ul><hr><h2 id="最佳化技巧" tabindex="-1">最佳化技巧 <a class="header-anchor" href="#最佳化技巧" aria-label="Permalink to &quot;最佳化技巧&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 設定 token 預算</span></span>
<span class="line"><span>&gt; create a workflow to refactor auth module, use 10k tokens</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 結合 /goal 定義完成條件</span></span>
<span class="line"><span>&gt; /goal all tests pass; create a workflow to fix failing tests</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 儲存 workflow 供重複使用</span></span>
<span class="line"><span>~/.claude/workflows/   # 個人</span></span>
<span class="line"><span>skills/                # 透過 skill 發布</span></span></code></pre></div><hr><h2 id="方案可用性" tabindex="-1">方案可用性 <a class="header-anchor" href="#方案可用性" aria-label="Permalink to &quot;方案可用性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>可用性</th></tr></thead><tbody><tr><td>Max、Team Premium、Enterprise PAYG、API</td><td>預設可用（Research Preview）</td></tr><tr><td>Pro</td><td>不支援</td></tr><tr><td>管理員</td><td>可關閉</td></tr></tbody></table><p>平台：CLI、Desktop、VS Code extension、Claude API、Bedrock、Vertex AI、Microsoft Foundry。</p>`,44)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
